// Wallet defines model for Wallet.
type Wallet struct {
	// AvailableSeconds 今から視聴できる秒数（ルールと今日の上限を反映）
	AvailableSeconds int `json:"availableSeconds"`

	// BalanceSeconds 残高
	BalanceSeconds int `json:"balanceSeconds"`

	// DeferredSeconds 朝に受け取る予定の報酬
	DeferredSeconds int `json:"deferredSeconds"`
	Policy          struct {
		DailyLimitSeconds int `json:"dailyLimitSeconds"`

		// Day 集計中の日
		Day  openapi_types.Date `json:"day"`
		Mode TimePolicyMode     `json:"mode"`

		// ResetAt 次に日が切り替わる時刻
		ResetAt time.Time `json:"resetAt"`

		// RewardSeconds 今日作業で得た秒数
		RewardSeconds int `json:"rewardSeconds"`

		// ViewedSeconds 今日視聴した秒数
		ViewedSeconds int `json:"viewedSeconds"`

		// WorkSeconds 今日記録した作業の秒数
		WorkSeconds int `json:"workSeconds"`
	} `json:"policy"`
	Revision int `json:"revision"`

	// Rules ルールの定数。表示の説明に使う
	Rules struct {
		BalanceCapSeconds int `json:"balanceCapSeconds"`

		// DailyRefillSeconds rewards モードで毎日この秒数まで補充する（fixed モードは dailyLimitSeconds まで）
		DailyRefillSeconds        int `json:"dailyRefillSeconds"`
		DailyRewardCapSeconds     int `json:"dailyRewardCapSeconds"`
		RegistrationRewardSeconds int `json:"registrationRewardSeconds"`
		RewardSecondsPerUnit      int `json:"rewardSecondsPerUnit"`

		// SleepBonusSeconds Shorts を見ずに眠れた夜の報酬の上限
		SleepBonusSeconds     int   `json:"sleepBonusSeconds"`
		ViewingChoicesSeconds []int `json:"viewingChoicesSeconds"`
		WorkSecondsPerReward  int   `json:"workSecondsPerReward"`
	} `json:"rules"`
}

